(() => {
  const r = rate / 100 / 12, n = years * 12;
  const pmt = r === 0 ? principal / n : principal * r / (1 - Math.pow(1 + r, -n));
  const f = x => x.toLocaleString("de-CH", {minimumFractionDigits: 2, maximumFractionDigits: 2});
  return htl.html`<div>
    <p>M = P·r / (1 − (1+r)<sup>−n</sup>), r = ${rate}%/12, n = ${n}</p>
    <p><b>Monthly payment: CHF ${f(pmt)}</b></p>
    <p>Total paid: CHF ${f(pmt * n)} · interest: CHF ${f(pmt * n - principal)}</p>
  </div>`;
})()

Plot.plot({
  width: 500,
  height: 350,
  color: { legend: true },
  marks: [
    Plot.arc(
      [
        { task: "meetings", hours: 30 },
        { task: "coding", hours: 50 },
        { task: "review", hours: 20 }
      ],
      {
        x: 0,
        y: 0,
        r: 140,
        start: (d, i, data) => data.slice(0, i).reduce((sum, v) => sum + v.hours, 0) / 100 * 2 * Math.PI - Math.PI / 2,
        end: (d, i, data) => data.slice(0, i + 1).reduce((sum, v) => sum + v.hours, 0) / 100 * 2 * Math.PI - Math.PI / 2,
        fill: "task",
        stroke: "white",
        strokeWidth: 2
      }
    )
  ]
})

(() => {
  const data = [{ task: "meetings", value: 30 }, { task: "coding", value: 50 }, { task: "review", value: 20 }];
  const w = 360, r = 150;
  const color = d3.scaleOrdinal(data.map(d => d.task), d3.schemeTableau10);
  const arcs = d3.pie().sort(null).value(d => d.value)(data);
  const arc = d3.arc().innerRadius(0).outerRadius(r);
  const label = d3.arc().innerRadius(r * 0.65).outerRadius(r * 0.65);
  const svg = d3.create("svg").attr("viewBox", [-w / 2, -w / 2, w, w]).attr("width", w).attr("height", w);
  svg.selectAll("path").data(arcs).join("path")
    .attr("d", arc).attr("fill", d => color(d.data.task)).attr("stroke", "white");
  svg.selectAll("text").data(arcs).join("text")
    .attr("transform", d => `translate(${label.centroid(d)})`)
    .attr("text-anchor", "middle").attr("fill", "white").attr("font-size", 13)
    .text(d => `${d.data.task} ${d.data.value}%`);
  return svg.node();
})()

